def code_from_text(text: str | None) -> ExclusionCode:
    """Infer a code from prose. Returns UNKNOWN rather than pretending."""
    if not text:
        return ExclusionCode.UNKNOWN
    for pattern, code in _PATTERNS:
        if pattern.search(text):
            return code
    return ExclusionCode.UNKNOWN

