_raise_for_status.source:
def _raise_for_status(status: int, parsed: Any, provider: str) -> None:
    detail = _describe(parsed)
    if status in (401, 403):
        if _is_quota(detail):
            raise RateLimitError(detail, provider=provider)
        raise AuthenticationError(detail or "credentials rejected", provider=provider)
    if status == 429:
        raise RateLimitError(detail or "rate limited", provider=provider)
    if status in (400, 422):
        raise ValidationError(detail or "request rejected", provider=provider)
    raise ProviderError(detail or f"HTTP {status}", provider=provider, status=status, raw=parsed)

_describe.source:
def _describe(parsed: Any) -> str:
    """Pull a usable message out of five different error envelope shapes."""
    if parsed is None:
        return ""
    if isinstance(parsed, str):
        return parsed[:400]
    if isinstance(parsed, dict):
        # Easyship: {"error": {"message": ..., "details": [...]}}
        err = parsed.get("error")
        if isinstance(err, dict):
            parts = [str(err.get("message") or "")]
            details = err.get("details")
            if isinstance(details, list):
                parts += [str(d) for d in details]
            return "; ".join(p for p in parts if p)[:600]
        if isinstance(err, str):
            return err[:400]
        # ShipStation v1: {"Message": ..., "ModelState": {...}}
        if "Message" in parsed:
            out = str(parsed["Message"])
            state = parsed.get("ModelState")
            if isinstance(state, dict):
                out += "; " + "; ".join(f"{k}: {v}" for k, v in state.items())
            return out[:600]
        # ShipEngine / ShipStation v2: {"errors": [{"message": ...}]}
        errors = parsed.get("errors")
        if isinstance(errors, list) and errors:
            texts = [str(e.get("message") if isinstance(e, dict) else e) for e in errors]
            return "; ".join(texts)[:600]
        if "detail" in parsed:
            return str(parsed["detail"])[:400]
    return str(parsed)[:400]

_rate.source:
def _rate(self, shipment: Shipment) -> Quote:
    if not shipment.is_multi_parcel:
        return self.adapter.rate_single(shipment)

    caps = self.adapter.capabilities
    if caps.native_multi_parcel:
        return self.adapter.rate_native_multi(shipment)

    # Emulate: rate each parcel alone, then combine. The per-parcel calls are
    # independent, so they run concurrently — a five-parcel shipment would
    # otherwise pay five round trips end to end. Results are read back in parcel
    # order because `combine_parcel_quotes` matches quotes to parcels by
    # position, and a rate belonging to the wrong parcel would be silently
    # mispriced rather than obviously broken.
    parcels = shipment.parcels
    legs = [self.adapter.single_parcel_shipment(shipment, parcel) for parcel in parcels]
    if len(legs) == 1:  # pragma: no cover - is_multi_parcel guarantees > 1
        per_parcel = [self.adapter.rate_single(legs[0])]
    else:
        workers = self.max_workers or len(legs)
        with ThreadPoolExecutor(
            max_workers=workers, thread_name_prefix="shipzil-parcel"
        ) as pool:
            per_parcel = list(pool.map(self.adapter.rate_single, legs))

    return combine_parcel_quotes(
        per_parcel,
        provider=self.adapter.name,
        via=f"{self.adapter.name}:fanoutx{len(parcels)}",
    )

