    """Not determinable: v2 API keys carry no test/live marker."""
    return None

rate_native_multi.source:
def rate_native_multi(self, shipment: Shipment) -> Quote:
    """Same endpoint — v2 simply takes more packages."""
    return self._rate(shipment)

_rate.source:
def _rate(self, shipment: Shipment) -> Quote:
    gap = _dimension_gap(shipment.parcels)
    if gap is not None:
        return Quote(excluded=(gap,), via=f"{self.name}:rates")

    _status, body = self.http(
        "POST",
        f"{BASE}/rates",
        headers=self._headers,
        json={
            "rate_options": {"carrier_ids": self.carrier_ids()},
            "shipment": {
                "ship_from": _address(shipment.from_address),
                "ship_to": _address(shipment.to_address),
                "packages": [
                    {
                        **_package(p),
                        **(
                            {"products": prods}
                            if (prods := self._products(p, shipment))
                            else {}
                        ),
                    }
                    for p in shipment.parcels
                ],
                **(
                    {"advanced_options": opts}
                    if (opts := self._advanced_options(shipment, shipment.parcels[0]))
                    else {}
                ),
                **({"ship_date": shipment.ship_date} if shipment.ship_date else {}),
                **(
                    {"customs": customs}
                    if (customs := self._customs(shipment))
                    else {}
                ),
            },
        },
        timeout=self.timeout,
        provider=self.name,
        idempotent=True,
    )

    response = body.get("rate_response") or {}
    parcel_count = len(shipment.parcels)
    strategy = Strategy.NATIVE

    rates = tuple(
        self._parse_rate(r, strategy=strategy, parcel_count=parcel_count)
        for r in (response.get("rates") or [])
    )
    excluded = tuple(self._parse_errors(response))

    if not rates and not excluded:
        excluded = (
            Exclusion(
                code=ExclusionCode.SERVICE_UNAVAILABLE,
                message="shipstation returned no rates and reported no errors",
                source="shipzil",
            ),
        )

    messages = tuple(
        str(m) for r in (response.get("rates") or []) for m in (r.get("warning_messages") or [])
    )
    return Quote(
        rates=rates, excluded=excluded, via=f"{self.name}:rates",
        strategy=strategy, messages=messages,
    )

_products.source:
@staticmethod
def _products(parcel: Parcel, shipment: Shipment) -> list[dict[str, Any]]:
    """Per-package customs lines, which is where ShipEngine wants them.

    This is the one provider that keeps the parcel association, so it walks
    the parcel's own items rather than the flattened shipment-wide list.
    """
    out: list[dict[str, Any]] = []
    for item in parcel.items:
        if item.value is None or item.weight is None:
            continue
        entry: dict[str, Any] = {
            "description": item.description,
            "quantity": item.quantity,
            # PER UNIT, not the line total. ShipStation's International
            # Shipments guide defines products[].value as "The declared value
            # of *each* item", with the emphasis theirs, and their own help
            # centre describes the UI equivalent as "Item Value (each)" with
            # "Total Value AUTO-CALCULATED ... as Quantity x Item Value".
            # shipzil sent line totals here until that was checked, which
            # multiplied the declared value by the quantity and would have
            # inflated duty on every multi-quantity line.
            "value": {
                "currency": (item.currency or "USD").lower(),
                "amount": float(item.value),
            },
            "weight": {"value": float(item.weight.to("oz")), "unit": "ounce"},
            "country_of_origin": (
                item.origin_country or shipment.from_address.country or "US"
            ),
        }
        if item.hs_code:
            entry["harmonized_tariff_code"] = item.hs_code
        if item.sku:
            entry["sku"] = item.sku
        out.append(entry)
    return out

_advanced_options.source:
@staticmethod
def _advanced_options(shipment: Shipment, parcel: Parcel) -> dict[str, Any]:
    """ShipEngine keeps hazmat booleans on the shipment and the full
    IATA declaration on `packages[].products[].dangerous_goods[]`.

    shipzil sends the shipment-level flags plus the emergency contact, which
    several carriers require whenever hazmat is present. The per-product
    declaration needs an itemised `products` array that shipzil does not
    model yet, so a fully regulated shipment is reported as a fidelity gap
    rather than sent half-declared.
    """
    opts: dict[str, Any] = {}
    dg = parcel.dangerous_goods
    if dg is not None and dg.contains:
        opts["dangerous_goods"] = True
        if dg.emergency_contact_name or dg.emergency_contact_phone:
            opts["dangerous_goods_contact"] = {
                "name": dg.emergency_contact_name or "",
                "phone": dg.emergency_contact_phone or "",
            }
        if dg.contains_alcohol:
            opts["contains_alcohol"] = True
        if dg.dry_ice is not None and dg.dry_ice.contains:
            opts["dry_ice"] = True
            # ShipEngine accepts four units; kilograms is unambiguous.
            opts["dry_ice_weight"] = {
                "value": float(dg.dry_ice.weight.to("kg")),
                "unit": "kilogram",
            }
    if shipment.duties_paid_by is DutiesPaidBy.SENDER:
        opts["delivered_duty_paid"] = True
    return opts

void.source:
def void(self, label: Label) -> bool:
    if not label.shipment_id:
        return False
    _status, body = self.http(
        "PUT", f"{BASE}/labels/{label.shipment_id}/void",
        headers=self._headers, timeout=self.timeout, provider=self.name, retries=0,
    )
    return bool((body or {}).get("approved"))

_parse_label.source:
def _parse_label(self, body: dict[str, Any]) -> Label:
    cost = body.get("shipment_cost") or {}
    download = body.get("label_download") or {}
    url = download.get("pdf") or download.get("href") or ""
    tracking = body.get("tracking_number") or ""
    if not url or not tracking:
        raise LabelPurchaseError(
            "shipstation returned no label url or tracking number", provider=self.name
        )
    currency = cost.get("currency")
    return Label(
        tracking_number=str(tracking),
        label_url=str(url),
        carrier=str(body.get("carrier_code") or ""),
        service=str(body.get("service_code") or ""),
        amount=Decimal(str(cost.get("amount") or 0)),
        currency=currency.upper() if isinstance(currency, str) else None,
        provider=self.name,
        is_test=self.is_test_mode(),
        shipment_id=str(body.get("label_id") or ""),
        raw=body,
    )

ShipStationV2Adapter.source:
class ShipStationV2Adapter(Adapter):
    name = "shipstation_v2"
    incoterm_style = "lower"
    # "The declared value of *each* item" — ShipStation International Shipments.
    customs_value_basis = "per_unit"
    # advanced_options.{dangerous_goods, dangerous_goods_contact, dry_ice,
    # dry_ice_weight, contains_alcohol}. The full IATA declaration exists on
    # packages[].products[].dangerous_goods[] (UN number, class, packing group,
    # transport mode, radioactive) but needs an itemised products array shipzil
    # does not build yet, so regulated_detail is deliberately NOT claimed.
    hazmat_fields = frozenset({"dry_ice", "contains_alcohol"})
    capabilities = Capabilities(
        native_multi_parcel=True,  # verified: 3 packages -> 7 real rates
        returns_currency=True,
        returns_delivery_estimate=True,
    )

    def __init__(
        self,
        api_key: str,
        *,
        carrier_ids: list[str] | None = None,
        timeout: float = 60.0,
    ):
        if not api_key:
            raise ValueError("shipstation v2 api key is required")
        self._headers = {"API-Key": api_key}
        self.timeout = timeout
        self._carrier_ids = carrier_ids

    # ── carriers ────────────────────────────────────────────────────

    def carrier_ids(self) -> list[str]:
        """Carrier ids on the account, fetched once.

        v2 rates against an explicit carrier list; without it the account default
        applies, which differs between tenants and makes results irreproducible.
        """
        if self._carrier_ids is None:
            _status, body = self.http(
                "GET", f"{BASE}/carriers", headers=self._headers,
                timeout=self.timeout, provider=self.name, idempotent=True,
            )
            self._carrier_ids = [
                c["carrier_id"] for c in (body.get("carriers") or []) if c.get("carrier_id")
            ]
        return self._carrier_ids

    # ── rating ──────────────────────────────────────────────────────

    def is_test_mode(self) -> bool | None:
        """Not determinable: v2 API keys carry no test/live marker."""
        return None

    def rate_single(self, shipment: Shipment) -> Quote:
        return self._rate(shipment)

    def rate_native_multi(self, shipment: Shipment) -> Quote:
        """Same endpoint — v2 simply takes more packages."""
        return self._rate(shipment)

    def _rate(self, shipment: Shipment) -> Quote:
        gap = _dimension_gap(shipment.parcels)
        if gap is not None:
            return Quote(excluded=(gap,), via=f"{self.name}:rates")

        _status, body = self.http(
            "POST",
            f"{BASE}/rates",
            headers=self._headers,
            json={
                "rate_options": {"carrier_ids": self.carrier_ids()},
                "shipment": {
                    "ship_from": _address(shipment.from_address),
                    "ship_to": _address(shipment.to_address),
                    "packages": [
                        {
                            **_package(p),
                            **(
                                {"products": prods}
                                if (prods := self._products(p, shipment))
                                else {}
                            ),
                        }
                        for p in shipment.parcels
                    ],
                    **(
                        {"advanced_options": opts}
                        if (opts := self._advanced_options(shipment, shipment.parcels[0]))
                        else {}
                    ),
                    **({"ship_date": shipment.ship_date} if shipment.ship_date else {}),
                    **(
                        {"customs": customs}
                        if (customs := self._customs(shipment))
                        else {}
                    ),
                },
            },
            timeout=self.timeout,
            provider=self.name,
            idempotent=True,
        )

        response = body.get("rate_response") or {}
        parcel_count = len(shipment.parcels)
        strategy = Strategy.NATIVE

        rates = tuple(
            self._parse_rate(r, strategy=strategy, parcel_count=parcel_count)
            for r in (response.get("rates") or [])
        )
        excluded = tuple(self._parse_errors(response))

        if not rates and not excluded:
            excluded = (
                Exclusion(
                    code=ExclusionCode.SERVICE_UNAVAILABLE,
                    message="shipstation returned no rates and reported no errors",
                    source="shipzil",
                ),
            )

        messages = tuple(
            str(m) for r in (response.get("rates") or []) for m in (r.get("warning_messages") or [])
        )
        return Quote(
            rates=rates, excluded=excluded, via=f"{self.name}:rates",
            strategy=strategy, messages=messages,
        )

    def _parse_errors(self, response: dict[str, Any]) -> list[Exclusion]:
        """v2's structured errors, plus any `invalid_rates` it rejected."""
        out: list[Exclusion] = []
        for err in response.get("errors") or []:
            if not isinstance(err, dict):
                continue
            message = str(err.get("message") or "")
            code = code_from_provider_code(err.get("error_code")) or code_from_text(message)
            # The provider gave a code, so this is fact rather than inference.
            source = "provider" if err.get("error_code") else "shipzil"
            out.append(
                Exclusion(
                    code=code,
                    message=message or "shipstation rejected this shipment",
                    carrier=err.get("carrier_code") or err.get("carrier_name"),
                    source=source,  # type: ignore[arg-type]
                )
            )
        for bad in response.get("invalid_rates") or []:
            if not isinstance(bad, dict):
                continue
            notes = "; ".join(str(m) for m in (bad.get("error_messages") or []))
            out.append(
                Exclusion(
                    code=code_from_text(notes),
                    message=notes or "shipstation marked this rate invalid",
                    carrier=bad.get("carrier_code"),
                    service=bad.get("service_type"),
                    source="shipzil",
                )
            )
        return out

    def _customs(self, shipment: Shipment) -> dict[str, Any] | None:
        """ShipEngine's shipment-level customs block.

        `customs_items` is **deprecated** here — the spec says "Please provide
        this information under `products` inside `packages`" — so the line detail
        goes on each package via `_products`, and only the shipment-wide fields
        live in this object.
        """
        if not self.is_cross_border(shipment):
            return None
        if not self.customs_lines(shipment):
            return None
        out: dict[str, Any] = {
            "contents": "merchandise",
            "non_delivery": "return_to_sender",
        }
        # Lowercase three-letter incoterms, from the spec's enum:
        # exw fca cpt cip dpu dap ddp fas fob cfr cif ddu daf deq des.
        # "delivery_duty_paid" is rejected with "Unknown TermsOfTradeCode value",
        # which is why this adapter declares incoterm_style = "lower".
        incoterm = self.render_incoterm(shipment)
        if incoterm:
            out["terms_of_trade_code"] = incoterm
        return out

    @staticmethod
    def _products(parcel: Parcel, shipment: Shipment) -> list[dict[str, Any]]:
        """Per-package customs lines, which is where ShipEngine wants them.

        This is the one provider that keeps the parcel association, so it walks
        the parcel's own items rather than the flattened shipment-wide list.
        """
        out: list[dict[str, Any]] = []
        for item in parcel.items:
            if item.value is None or item.weight is None:
                continue
            entry: dict[str, Any] = {
                "description": item.description,
                "quantity": item.quantity,
                # PER UNIT, not the line total. ShipStation's International
                # Shipments guide defines products[].value as "The declared value
                # of *each* item", with the emphasis theirs, and their own help
                # centre describes the UI equivalent as "Item Value (each)" with
                # "Total Value AUTO-CALCULATED ... as Quantity x Item Value".
                # shipzil sent line totals here until that was checked, which
                # multiplied the declared value by the quantity and would have
                # inflated duty on every multi-quantity line.
                "value": {
                    "currency": (item.currency or "USD").lower(),
                    "amount": float(item.value),
                },
                "weight": {"value": float(item.weight.to("oz")), "unit": "ounce"},
                "country_of_origin": (
                    item.origin_country or shipment.from_address.country or "US"
                ),
            }
            if item.hs_code:
                entry["harmonized_tariff_code"] = item.hs_code
            if item.sku:
                entry["sku"] = item.sku
            out.append(entry)
        return out

    @staticmethod
    def _advanced_options(shipment: Shipment, parcel: Parcel) -> dict[str, Any]:
        """ShipEngine keeps hazmat booleans on the shipment and the full
        IATA declaration on `packages[].products[].dangerous_goods[]`.

        shipzil sends the shipment-level flags plus the emergency contact, which
        several carriers require whenever hazmat is present. The per-product
        declaration needs an itemised `products` array that shipzil does not
        model yet, so a fully regulated shipment is reported as a fidelity gap
        rather than sent half-declared.
        """
        opts: dict[str, Any] = {}
        dg = parcel.dangerous_goods
        if dg is not None and dg.contains:
            opts["dangerous_goods"] = True
            if dg.emergency_contact_name or dg.emergency_contact_phone:
                opts["dangerous_goods_contact"] = {
                    "name": dg.emergency_contact_name or "",
                    "phone": dg.emergency_contact_phone or "",
                }
            if dg.contains_alcohol:
                opts["contains_alcohol"] = True
            if dg.dry_ice is not None and dg.dry_ice.contains:
                opts["dry_ice"] = True
                # ShipEngine accepts four units; kilograms is unambiguous.
                opts["dry_ice_weight"] = {
                    "value": float(dg.dry_ice.weight.to("kg")),
                    "unit": "kilogram",
                }
        if shipment.duties_paid_by is DutiesPaidBy.SENDER:
            opts["delivered_duty_paid"] = True
        return opts

    def _parse_rate(
        self, data: dict[str, Any], *, strategy: Strategy, parcel_count: int
    ) -> Rate:
        shipping = data.get("shipping_amount") or {}
        other = data.get("other_amount") or {}
        # Base cost is shipping plus mandatory other charges, mirroring how v1
        # splits shipmentCost/otherCost. Insurance and confirmation are opt-in
        # add-ons and stay out of the comparable figure.
        amount = Decimal(str(shipping.get("amount") or 0)) + Decimal(str(other.get("amount") or 0))
        currency = shipping.get("currency")
        return Rate(
            carrier=str(data.get("carrier_friendly_name") or data.get("carrier_code") or ""),
            service=str(data.get("service_type") or ""),
            service_key=ServiceKey.build(
                provider=self.name,
                # carrier_code is already lowercase and stable; friendly_name
                # carries a registered-trademark glyph ("UPS® Ground").
                carrier=str(data.get("carrier_code") or data.get("carrier_friendly_name") or ""),
                service=str(data.get("service_code") or data.get("service_type") or ""),
            ),
            amount=amount,
            currency=currency.upper() if isinstance(currency, str) else None,
            delivery_days=data.get("delivery_days"),
            guaranteed=data.get("guaranteed_service"),
            provider=self.name,
            service_code=data.get("service_code"),
            strategy=strategy,
            parcel_count=parcel_count,
            raw=data,
        )

    # ── buying ──────────────────────────────────────────────────────

    def buy(self, shipment: Shipment, rate: Rate) -> Label:
        """Purchase from a previously returned `rate_id`.

        Never exercised against live credentials in this repo's test suite: the
        only ShipStation keys available are production.

        ShipStation v2 documents exactly two headers (API-Key, Content-Type),
        so the key is always None here and the only protection is retries=0.
        """
        raw = rate.raw if isinstance(rate.raw, dict) else {}
        rate_id = raw.get("rate_id")
        if not rate_id:
            raise LabelPurchaseError(
                "this rate has no shipstation rate_id and cannot be bought",
                provider=self.name,
            )
        _status, body = self.http(
            "POST",
            f"{BASE}/labels/rates/{rate_id}",
            headers=self._headers,
            json={"validate_address": "no_validation"},
            timeout=self.timeout,
            provider=self.name,
            retries=0,
        )
        return self._parse_label(body)

    def void(self, label: Label) -> bool:
        if not label.shipment_id:
            return False
        _status, body = self.http(
            "PUT", f"{BASE}/labels/{label.shipment_id}/void",
            headers=self._headers, timeout=self.timeout, provider=self.name, retries=0,
        )
        return bool((body or {}).get("approved"))

    def _parse_label(self, body: dict[str, Any]) -> Label:
        cost = body.get("shipment_cost") or {}
        download = body.get("label_download") or {}
        url = download.get("pdf") or download.get("href") or ""
        tracking = body.get("tracking_number") or ""
        if not url or not tracking:
            raise LabelPurchaseError(
                "shipstation returned no label url or tracking number", provider=self.name
            )
        currency = cost.get("currency")
        return Label(
            tracking_number=str(tracking),
            label_url=str(url),
            carrier=str(body.get("carrier_code") or ""),
            service=str(body.get("service_code") or ""),
            amount=Decimal(str(cost.get("amount") or 0)),
            currency=currency.upper() if isinstance(currency, str) else None,
            provider=self.name,
            is_test=self.is_test_mode(),
            shipment_id=str(body.get("label_id") or ""),
            raw=body,
        )

_address.source:
def _address(addr: Address) -> dict[str, Any]:
    out: dict[str, Any] = {
        "address_line1": addr.street1,
        "city_locality": addr.city,
        "postal_code": addr.postal_code,
        "country_code": addr.country,
    }
    if addr.state:
        out["state_province"] = addr.state
    if addr.street2:
        out["address_line2"] = addr.street2
    if addr.name:
        out["name"] = addr.name
    if addr.company:
        out["company_name"] = addr.company
    if addr.phone:
        out["phone"] = addr.phone
    if addr.residential is not None:
        out["address_residential_indicator"] = "yes" if addr.residential else "no"
    else:
        # Explicit "unknown" rather than omission: ShipEngine has that value and
        # defaults to it, so saying so is more honest than staying silent.
        out["address_residential_indicator"] = "unknown"
    return out

_package.source:
def _package(parcel: Parcel) -> dict[str, Any]:
    weight = parcel.weight or parcel.derived_weight
    assert weight is not None  # guarded by _dimension_gap
    out: dict[str, Any] = {"weight": {"value": float(weight.to("oz")), "unit": "ounce"}}
    if parcel.insured_value is not None:
        out["insured_value"] = {"currency": "usd", "amount": float(parcel.insured_value)}
    if parcel.packaging is not None:
        # A carrier package code supplies the dimensions, so they are omitted.
        out["package_code"] = parcel.packaging.code
        return out
    if parcel.dimensions is not None:
        length, width, height = parcel.dimensions.to("in")
        out["dimensions"] = {
            "unit": "inch",
            "length": float(length),
            "width": float(width),
            "height": float(height),
        }
    return out

_dimension_gap.source:
def _dimension_gap(parcels: tuple[Parcel, ...]) -> Exclusion | None:
    for index, parcel in enumerate(parcels):
        if parcel.weight is None and parcel.derived_weight is None:
            return Exclusion(
                code=ExclusionCode.DIMENSIONS_REQUIRED,
                message=(
                    f"shipstation needs an explicit weight for parcel {index + 1}; it cannot "
                    "derive one from items"
                ),
                source="shipzil",
            )
    return None

is_test_mode.source:
def is_test_mode(self) -> bool | None:
    """Determinable: sandbox is a separate host, selected at construction."""
    return self.sandbox

rate_single.source:
def rate_single(self, shipment: Shipment) -> Quote:
    parcel = shipment.parcels[0]
    gap = self._input_gap(parcel)
    if gap is not None:
        return Quote(excluded=(gap,), via=f"{self.name}:rates")

    payload: dict[str, Any] = {
        "origin_address": _address(shipment.from_address),
        "destination_address": _address(shipment.to_address),
        "parcels": [self._parcel(parcel)],
        "shipping_settings": {"units": {"weight": "kg", "dimensions": "cm"}},
    }
    incoterms = self.render_incoterm(shipment)
    if incoterms:
        payload["incoterms"] = incoterms
    residential = shipment.to_address.residential
    if residential is not None:
        # Destination only; Easyship has no origin residential field.
        payload["set_as_residential"] = residential
    try:
        _status, body = self.http(
            "POST", self._url("/rates"), headers=self._headers, json=payload,
            timeout=self.timeout, provider=self.name,
            idempotent=True,
        )
    except ValidationError as exc:
        # Easyship states refusals as 422 with a real message; keep it.
        text = str(exc)
        return Quote(
            excluded=(
                Exclusion(code=code_from_text(text), message=text, source="shipzil"),
            ),
            via=f"{self.name}:rates",
        )

    rates = tuple(self._parse_rate(r) for r in (body.get("rates") or []))
    excluded: tuple[Exclusion, ...] = ()
    if not rates:
        excluded = (
            Exclusion(
                code=ExclusionCode.SERVICE_UNAVAILABLE,
                message="easyship returned no rates",
                source="shipzil",
            ),
        )
    return Quote(
        rates=rates, excluded=excluded, via=f"{self.name}:rates", strategy=Strategy.NATIVE
    )

_surcharges.source:
@classmethod
def _surcharges(cls, data: dict[str, Any]) -> tuple[tuple[str, Decimal], ...]:
    """Non-zero cost components.

    Easyship reports 25 of these, so keeping only the total hides the gap
    between base carriage and the amount charged. `residential_full_fee` is
    reported even when it is not applied, which lets a caller see the exposure
    of an address that has not been classified.
    """
    out = []
    for key in cls._SURCHARGE_KEYS:
        raw = data.get(key)
        if raw in (None, "", 0, 0.0):
            continue
        try:
            value = Decimal(str(raw))
        except (ArithmeticError, ValueError):
            continue
        if value:
            out.append((key, value))
    return tuple(out)

_await_label.source:
def _await_label(self, shipment_id: str, rate: Rate) -> Label:
    """Bounded poll, for when the synchronous flag did not settle the state."""
    deadline = time.monotonic() + self.label_timeout
    state = ""
    while time.monotonic() < deadline:
        time.sleep(self.poll_interval)
        _status, body = self.http(
            "GET", self._url(f"/shipments/{shipment_id}"),
            headers=self._headers, timeout=self.timeout,
            provider=self.name, idempotent=True,
        )
        record = body.get("shipment") or body
        state = str(record.get("label_state") or "")
        if state == "generated":
            return self._parse_label(body, fallback_id=shipment_id, rate=rate)
        if state == "failed":
            raise LabelPurchaseError(
                f"easyship label generation failed for {shipment_id}",
                provider=self.name,
            )
    raise LabelPurchaseError(
        f"easyship label for {shipment_id} was still {state or 'unknown'} after "
        f"{self.label_timeout:.0f}s. The shipment is confirmed and may still "
        f"complete; check label_state rather than buying again.",
        provider=self.name,
    )

_parse_label.source:
def _parse_label(
    self, body: dict[str, Any], *, fallback_id: str, rate: Rate
) -> Label:
    record = body.get("shipment") or body
    # There is no flat tracking_number. Easyship returns a `trackings` array,
    # one entry per leg, each with handler / leg_number / tracking_number and
    # a nullable local_tracking_number. Reading the non-existent flat field
    # returned an empty tracking number on every successful purchase.
    tracking = ""
    legs = record.get("trackings") or []
    for leg in sorted(
        (t for t in legs if isinstance(t, dict)),
        key=lambda t: t.get("leg_number") or 0,
    ):
        tracking = str(
            leg.get("tracking_number")
            or leg.get("local_tracking_number")
            or leg.get("alternate_tracking_number")
            or ""
        )
        if tracking:
            break
    if not tracking:
        tracking = str(record.get("tracking_number") or "")
    legs = tuple(
        TrackingLeg(
            tracking_number=str(t.get("tracking_number") or ""),
            leg_number=int(t.get("leg_number") or 1),
            handler=t.get("handler"),
            local_tracking_number=t.get("local_tracking_number"),
            alternate_tracking_number=t.get("alternate_tracking_number"),
        )
        for t in sorted(
            (x for x in (record.get("trackings") or []) if isinstance(x, dict)),
            key=lambda x: x.get("leg_number") or 0,
        )
        if t.get("tracking_number")
    )
    docs = record.get("shipping_documents") or []
    url = ""
    for doc in docs:
        if isinstance(doc, dict) and doc.get("category") in {"label", None}:
            url = doc.get("url") or ""
            if url:
                break
    if not url:
        url = (record.get("label_url") or "")
    if not tracking and not url:
        raise LabelPurchaseError(
            f"easyship label not ready (label_state={record.get('label_state')!r})",
            provider=self.name,
        )
    return Label(
        tracking_number=str(tracking),
        label_url=str(url),
        carrier=rate.carrier,
        service=rate.service,
        amount=rate.amount,
        currency=rate.currency,
        provider=self.name,
        is_test=self.is_test_mode(),
        shipment_id=str(record.get("easyship_shipment_id") or fallback_id),
        tracking_legs=legs,
        raw=body,
    )

void.source:
def void(self, label: Label) -> bool:
    if not label.shipment_id:
        return False
    _status, body = self.http(
        "PATCH", self._url(f"/shipments/{label.shipment_id}/cancel"),
        headers=self._headers, json={}, timeout=self.timeout,
        provider=self.name, retries=0,
    )
    record = (body or {}).get("shipment") or body or {}
    return str(record.get("label_state") or "").lower() in {"voided", "cancelled", "canceled"}

_parcel.source:
def _parcel(self, parcel: Parcel) -> dict[str, Any]:
    out: dict[str, Any] = {}
    weight = parcel.weight or parcel.derived_weight
    if weight is not None:
        out["total_actual_weight"] = float(weight.to("kg"))
    if parcel.dimensions is not None:
        length, width, height = parcel.dimensions.to("cm")
        out["box"] = {
            "length": float(length),
            "width": float(width),
            "height": float(height),
        }
    if parcel.packaging is not None:
        # A slug carries the dimensions, so it replaces `box`.
        out["box"] = {"slug": parcel.packaging.code}
    if parcel.items:
        out["items"] = [self._item(i, parcel.dangerous_goods) for i in parcel.items]
    else:
        # Easyship requires at least one item. Describe the parcel itself
        # rather than inventing contents it does not have.
        out["items"] = [
            self._item(
                Item(
                    description="Merchandise",
                    quantity=1,
                    weight=weight,
                    value=Decimal("10.00"),
                    category=self.default_category,
                )
            )
        ]
    return out

_hazmat_item_flags.source:
@staticmethod
def _hazmat_item_flags(dg: DangerousGoods | None) -> dict[str, Any]:
    """Easyship carries hazmat per item, and only these three flags.

    `contains_battery_pi966` / `pi967` are the IATA packing instructions and
    are not interchangeable. Anything else in a DangerousGoods — UN number,
    hazard class, packing group, dry ice — has nowhere to go here, which the
    adapter reports rather than dropping silently.
    """
    if dg is None or not dg.contains:
        return {}
    out: dict[str, Any] = {}
    if dg.lithium_batteries is LithiumBatteryPacking.PACKED_WITH_EQUIPMENT:
        out["contains_battery_pi966"] = True
    elif dg.lithium_batteries is LithiumBatteryPacking.CONTAINED_IN_EQUIPMENT:
        out["contains_battery_pi967"] = True
    if dg.contains_liquids:
        out["contains_liquids"] = True
    return out

_item.source:
def _item(self, item: Item, dg: DangerousGoods | None = None) -> dict[str, Any]:
    out: dict[str, Any] = {
        "description": item.description,
        "quantity": item.quantity,
        "declared_currency": item.currency,
        "declared_customs_value": float(item.value if item.value is not None else 10),
    }
    if item.weight is not None:
        out["actual_weight"] = float(item.weight.to("kg"))
    if item.dimensions is not None:
        length, width, height = item.dimensions.to("cm")
        out["dimensions"] = {
            "length": float(length),
            "width": float(width),
            "height": float(height),
        }
    if item.sku:
        out["sku"] = item.sku
    if item.hs_code:
        out["hs_code"] = item.hs_code
    category = item.category or self.default_category
    if category:
        out["category"] = category
    if item.origin_country:
        out["origin_country_alpha2"] = item.origin_country
    out.update(self._hazmat_item_flags(dg))
    return out

_address.source:
def _address(addr: Address) -> dict[str, Any]:
    out: dict[str, Any] = {
        "line_1": addr.street1,
        "city": addr.city,
        "postal_code": addr.postal_code,
        "country_alpha2": addr.country,
    }
    if addr.state:
        out["state"] = addr.state
    if addr.street2:
        out["line_2"] = addr.street2
    if addr.name:
        out["contact_name"] = addr.name
    if addr.company:
        out["company_name"] = addr.company
    if addr.phone:
        out["contact_phone"] = addr.phone
    if addr.email:
        out["contact_email"] = addr.email
    return out

rate_single.source:
def rate_single(self, shipment: Shipment) -> Quote:
    parcel = shipment.parcels[0]
    if not parcel.has_dimensions:
        # See the Shippo note: a packageCode supplies the dimensions.
        return Quote(
            excluded=(
                Exclusion(
                    code=ExclusionCode.DIMENSIONS_REQUIRED,
                    message=(
                        "shipstation v1 needs parcel dimensions, or a packageCode via "
                        "Parcel(packaging=PackagingTemplate(...)); it cannot derive a box "
                        "from items"
                    ),
                    source="shipzil",
                ),
            ),
            via=f"{self.name}:getrates",
            strategy=Strategy.NATIVE,
        )

    codes = self.carrier_codes()
    if not codes:
        return Quote(
            excluded=(
                Exclusion(
                    code=ExclusionCode.CARRIER_ACCOUNT_MISCONFIGURED,
                    message=(
                        "no carriers are connected to this shipstation v1 account, and v1 "
                        "requires an explicit carrierCode on every rate request"
                    ),
                    source="shipzil",
                ),
            ),
            via=f"{self.name}:getrates",
            strategy=Strategy.NATIVE,
        )

    rates: list[Rate] = []
    excluded: list[Exclusion] = []
    for code in codes:
        try:
            rates.extend(self._rates_for_carrier(code, shipment))
        except RateLimitError as exc:
            # 40 req/min, and one request per carrier. Continuing would just
            # collect more 429s, so stop and report the carriers not reached.
            unreached = list(codes[codes.index(code) :])
            excluded.append(
                Exclusion(
                    code=ExclusionCode.RATE_LIMITED,
                    message=(
                        f"{exc}. Stopped after rating "
                        f"{len(codes) - len(unreached)} of {len(codes)} carriers; "
                        f"not reached: {', '.join(unreached)}"
                    ),
                    carrier=code,
                    source="provider",
                )
            )
            break
        except (ProviderError, ValidationError) as exc:
            # One carrier refusing must not discard the others' rates.
            # AuthenticationError is deliberately not caught: bad credentials
            # are not a per-carrier condition and should surface immediately.
            excluded.append(
                Exclusion(
                    code=code_from_text(str(exc)),
                    message=str(exc),
                    carrier=code,
                    source="provider",
                )
            )

    return Quote(
        rates=tuple(rates),
        excluded=tuple(excluded),
        via=f"{self.name}:getratesx{len(codes)}",
        strategy=Strategy.NATIVE,
    )

buy.source:
def buy(self, shipment: Shipment, rate: Rate) -> Label:
    """Create a label via `POST /shipments/createlabel`.


    When `test_labels` is True this sends `testLabel: true`, which returns a
    real label response without purchasing postage.
    """
    parcel = shipment.parcels[0]
    service_code = (rate.service_code or "").strip()
    if not service_code:
        raise LabelPurchaseError(
            "this rate has no shipstation v1 serviceCode and cannot be bought",
            provider=self.name,
        )
    carrier_code = ""
    if isinstance(rate.raw, dict):
        carrier_code = str(rate.raw.get("_carrier_code") or "")
    if not carrier_code:
        raise LabelPurchaseError(
            "this rate is missing the carrierCode v1 requires on label creation",
            provider=self.name,
        )

    payload: dict[str, Any] = {
        "carrierCode": carrier_code,
        "serviceCode": service_code,
        "packageCode": (
            parcel.packaging.code
            if parcel.packaging is not None
            else str((rate.raw or {}).get("packageCode") or "package")
        ),
        "confirmation": self.confirmation,
        "shipFrom": _address(shipment.from_address),
        "shipTo": _address(shipment.to_address),
        "weight": {
            "value": float(parcel.weight.to("oz")) if parcel.weight else 0.0,
            "units": "ounces",
        },
        "testLabel": self.test_labels,
    }
    intl = self._international_options(shipment)
    if intl:
        # v1 accepts customs only on createlabel; getrates has no such field.
        payload["internationalOptions"] = intl
    if parcel.dimensions is not None:
        length, width, height = parcel.dimensions.to("in")
        payload["dimensions"] = {
            "units": "inches",
            "length": float(length),
            "width": float(width),
            "height": float(height),
        }

    _status, body = self.http(
        "POST",
        f"{BASE}/shipments/createlabel",
        headers=self._headers,
        json=payload,
        timeout=self.timeout,
        provider=self.name,
        retries=0,  # never blind-retry a purchase
    )
    return self._label(body, rate)

void.source:
def void(self, label: Label) -> bool:
    raw = label.raw if isinstance(label.raw, dict) else {}
    shipment_id = raw.get("shipmentId")
    # A test label has shipmentId -1 because no shipment record exists.
    # Sending that to voidlabel is a guaranteed pointless failure, so refuse
    # locally and say why rather than letting the provider reject it.
    if label.is_test or shipment_id == -1:
        raise LabelPurchaseError(
            "this is a test label (shipmentId -1); there is no shipment to void. "
            "Test labels are not purchased, so nothing needs refunding.",
            provider=self.name,
        )
    if shipment_id is None:
        raise LabelPurchaseError(
            "this label has no shipstation v1 shipmentId and cannot be voided",
            provider=self.name,
        )
    _status, body = self.http(
        "POST",
        f"{BASE}/shipments/voidlabel",
        headers=self._headers,
        json={"shipmentId": shipment_id},
        timeout=self.timeout,
        provider=self.name,
        retries=0,
    )
    data = body if isinstance(body, dict) else {}
    return bool(data.get("approved"))

__init__.source:
def __init__(self, api_token: str, *, timeout: float = 90.0):
    if not api_token:
        raise ValueError("shippo api token is required")
    self.api_token = api_token
    self.timeout = timeout
    self._headers = {"Authorization": f"ShippoToken {api_token}"}

is_test_mode.source:
def is_test_mode(self) -> bool | None:
    """Determinable: Shippo prefixes test tokens with shippo_test_."""
    return self.is_test_token

rate_single.source:
def rate_single(self, shipment: Shipment) -> Quote:
    parcel = shipment.parcels[0]
    gap = _dimension_gap(parcel)
    if gap is not None:
        return Quote(excluded=(gap,), via=f"{self.name}:shipments")

    _status, body = self.http(
        "POST",
        f"{BASE}/shipments/",
        headers=self._headers,
        json={
            "address_from": _address(shipment.from_address),
            "address_to": _address(shipment.to_address),
            "parcels": [_parcel(parcel)],
            # Synchronous by explicit request; Shippo defaults to async.
            "async": False,
            **({"extra": extra} if (extra := self._extra(shipment, parcel)) else {}),
            **(
                {"customs_declaration": customs}
                if (customs := self._customs(shipment))
                else {}
            ),
        },
        timeout=self.timeout,
        provider=self.name,
        idempotent=True,
    )

    shipment_id = str(body.get("object_id") or "")
    rates = tuple(
        self._parse_rate(r, shipment_id=shipment_id) for r in (body.get("rates") or [])
    )
    messages = [_message_text(m) for m in (body.get("messages") or [])]
    messages = [m for m in messages if m]

    excluded: tuple[Exclusion, ...] = ()
    if not rates:
        excluded = tuple(self._exclusions(body.get("messages") or []))
        if not excluded:
            excluded = (
                Exclusion(
                    code=ExclusionCode.SERVICE_UNAVAILABLE,
                    message=(
                        f"shippo returned status {body.get('status')!r} with no rates "
                        "and no messages"
                    ),
                    source="shipzil",
                ),
            )
    return Quote(
        rates=rates,
        excluded=excluded,
        via=f"{self.name}:shipments",
        strategy=Strategy.NATIVE,
        messages=tuple(messages),
    )

_extra.source:
@staticmethod
def _extra(shipment: Shipment, parcel: Parcel) -> dict[str, Any]:
    """Shippo puts hazmat on the shipment's `extra`, not on the parcel.

    Its own note: dangerous-goods contents restrict eligibility to certain
    USPS service levels, so this changes *which rates come back*, not only
    the price. Omitting it silently produces a rate the carrier will refuse.
    """
    extra: dict[str, Any] = {}
    dg = parcel.dangerous_goods
    if dg is not None and dg.contains:
        goods: dict[str, Any] = {"contains": True}
        if dg.lithium_batteries is not LithiumBatteryPacking.NONE:
            # Shippo has one boolean; the PI966/PI967 distinction is lost
            # here, which the adapter reports via _hazmat_fidelity_gap.
            goods["lithium_batteries"] = {"contains": True}
        if dg.biological_material:
            goods["biological_material"] = {"contains": True}
        extra["dangerous_goods"] = goods
        if dg.dry_ice is not None and dg.dry_ice.contains:
            # Kilograms only, and must not exceed the parcel weight.
            extra["dry_ice"] = {
                "contains_dry_ice": True,
                "weight": str(dg.dry_ice.weight.to("kg")),
            }
        if dg.contains_alcohol:
            alcohol: dict[str, Any] = {"contains_alcohol": True}
            if dg.alcohol_recipient:
                alcohol["recipient_type"] = dg.alcohol_recipient
            extra["alcohol"] = alcohol
    if parcel.insured_value is not None:
        extra["insurance"] = {
            "amount": str(parcel.insured_value),
            "currency": "USD",
        }
    return extra

_message_text.source:
def _message_text(msg: Any) -> str:
    if isinstance(msg, dict):
        source = msg.get("source")
        text = msg.get("text") or msg.get("message") or ""
        return f"{source} - {text}" if source and text else str(text or "")
    return str(msg or "")

_address.source:
def _address(addr: Address) -> dict[str, Any]:
    out: dict[str, Any] = {
        "street1": addr.street1,
        "city": addr.city,
        "zip": addr.postal_code,
        "country": addr.country,
    }
    if addr.state:
        out["state"] = addr.state
    if addr.street2:
        out["street2"] = addr.street2
    if addr.name:
        out["name"] = addr.name
    if addr.company:
        out["company"] = addr.company
    if addr.phone:
        out["phone"] = addr.phone
    if addr.email:
        out["email"] = addr.email
    if addr.street3:
        out["street3"] = addr.street3
    residential = addr.residential
    if residential is not None:
        # Omitted when unknown. Sending False would assert "commercial" and
        # understate the quote by the residential surcharge, ~$6 on UPS.
        out["is_residential"] = residential
    return out

_dimension_gap.source:
def _dimension_gap(parcel: Parcel) -> Exclusion | None:
    """Shippo needs both a weight and a box; it derives neither."""
    if parcel.weight is None and parcel.derived_weight is None:
        return Exclusion(
            code=ExclusionCode.DIMENSIONS_REQUIRED,
            message=(
                "shippo needs an explicit parcel weight; it cannot derive one from items"
            ),
            source="shipzil",
        )
    if not parcel.has_dimensions:
        # has_dimensions, not `dimensions is None`: a carrier template supplies
        # the size, and Shippo's schema requires the dimension fields to be
        # ABSENT alongside one. Checking `dimensions` directly refused every
        # flat-rate parcel before the request was even built.
        return Exclusion(
            code=ExclusionCode.DIMENSIONS_REQUIRED,
            message=(
                "shippo requires parcel dimensions as well as a weight, or a carrier "
                "template via Parcel(packaging=PackagingTemplate(...))"
            ),
            source="shipzil",
        )
    return None

rate_single.source:
@abstractmethod
def rate_single(self, shipment: Shipment) -> Quote:
    """Rate a shipment containing exactly one parcel.

    Every adapter must implement this; it is the unit the fan-out strategy
    composes when a provider cannot do multi-parcel.
    """

is_cross_border.source:
@staticmethod
def is_cross_border(shipment: Shipment) -> bool:
    return (shipment.from_address.country or "US") != (
        shipment.to_address.country or "US"
    )

render_eei.source:
def render_eei(self, shipment: Shipment) -> str | None:
    """The exemption in this provider's spelling, or None to refuse."""
    token = shipment.derived_eei_exemption
    if not token:
        return None
    if self.eei_style == "prose":
        return _EEI_PROSE.get(token, token)
    return token

customs_gap.source:
def customs_gap(self, shipment: Shipment) -> Exclusion | None:
    """Refuse a cross-border shipment shipzil cannot declare.

    Deliberately raised at *rating* time. Providers happily rate an
    international shipment with no customs data and then fail the purchase —
    Shippo answered a fully rated US-to-Canada shipment with "USPS - Customs
    declaration is required for international shipments via the USPS". A rate
    that can never be bought is worse than no rate.
    """
    if not self.is_cross_border(shipment):
        return None
    if not self.customs_lines(shipment):
        return Exclusion(
            code=ExclusionCode.CUSTOMS_DECLARATION_REQUIRED,
            message=(
                f"{self.name} needs a customs declaration for a cross-border "
                "shipment. Give every Item a weight and a value, and an hs_code "
                "where you have one. Rating would succeed without them and the "
                "purchase would then fail."
            ),
            source="shipzil",
        )
    if self.render_eei(shipment) is None:
        return Exclusion(
            code=ExclusionCode.CUSTOMS_DECLARATION_REQUIRED,
            message=(
                f"declared value {shipment.declared_value} exceeds the $2,500 "
                "NOEEI 30.37(a) threshold, so this export needs an AES filing and "
                "an ITN that shipzil cannot produce. Set "
                "Shipment(eei_exemption=...) with your ITN or the correct citation."
            ),
            source="shipzil",
        )
    return None

hazmat_fidelity_gap.source:
def hazmat_fidelity_gap(self, shipment: Shipment) -> Exclusion | None:
    """Report hazmat detail this provider will drop.

    Not a refusal. Plenty of hazmat ships lawfully under limited or excepted
    quantity with far less paperwork than a fully regulated consignment, and
    deciding which applies is the shipper's call, not shipzil's. But a
    declaration silently discarded is exactly the failure this library
    exists to surface, so it comes back as an `Exclusion` on the quote.
    """
    declared: set[str] = set()
    for dg in shipment.dangerous_goods:
        if dg.lithium_batteries is not LithiumBatteryPacking.NONE:
            declared.add("lithium_batteries")
        if dg.biological_material:
            declared.add("biological_material")
        if dg.contains_liquids:
            declared.add("contains_liquids")
        if dg.contains_alcohol:
            declared.add("contains_alcohol")
        if dg.dry_ice is not None:
            declared.add("dry_ice")
        if dg.un_number or dg.hazard_class or dg.packing_group:
            declared.add("regulated_detail")
        if dg.radioactive:
            declared.add("radioactive")
    dropped = sorted(declared - self.hazmat_fields)
    if not dropped:
        return None
    return Exclusion(
        code=ExclusionCode.HAZMAT_DETAIL_UNSUPPORTED,
        message=(
            f"{self.name} cannot carry these declared hazmat details: "
            f"{', '.join(dropped)}. They will not reach the carrier, so the "
            "shipment may be under-declared. Use a provider that supports "
            "them, or file the declaration outside shipzil."
        ),
        source="shipzil",
    )

is_test_mode.source:
def is_test_mode(self) -> bool | None:
    """True/False where determinable, None where the provider gives no hint."""
    return None

void.source:
def void(self, label: Label) -> bool:
    """Refund/cancel an unused label."""
    raise NotImplementedError(f"{self.name} does not support voiding via shipzil yet")
